import { attachFrame } from '../config/utils';
import { browserTest as it, expect } from '../config/browserTest';
import fs from 'fs';

import type { BrowserContext } from 'playwright-core';

it('should capture local storage', async ({ contextFactory }) => {
  const context = await contextFactory();
  const page1 = await context.newPage();
  await page1.route('**/*', route => {
    route.fulfill({ body: '<html></html>' }).catch(() => {});
  });
  await page1.goto('https://www.example.com');
  await page1.evaluate(() => {
    localStorage['name1'] = 'value1';
  });
  await page1.goto('https://www.domain.com');
  await page1.evaluate(() => {
    localStorage['name2'] = 'value2';
  });
  const { origins } = await context.storageState();
  expect(origins).toEqual([{
    origin: 'https://www.domain.com',
    localStorage: [{
      name: 'name2',
      value: 'value2'
    }],
  }, {
    origin: 'https://www.example.com',
    localStorage: [{
      name: 'name1',
      value: 'value1'
    }],
  }]);
});

it('should set local storage', async ({ contextFactory, channel }) => {
  it.fixme(channel?.startsWith('msedge'), 'Network.clearBrowserCache sometimes stalls');

  const context = await contextFactory({
    storageState: {
      cookies: [],
      origins: [
        {
          origin: 'https://www.example.com',
          localStorage: [{
            name: 'name1',
            value: 'value1'
          }]
        },
      ]
    }
  });
  const page = await context.newPage();
  await page.route('**/*', route => {
    route.fulfill({ body: '<html></html>' }).catch(() => {});
  });
  await page.goto('https://www.example.com');
  const localStorage = await page.evaluate('window.localStorage');
  expect(localStorage).toEqual({ name1: 'value1' });

  // Now use setStorageState to replace the storage
  await context.setStorageState({
    cookies: [],
    origins: [
      {
        origin: 'https://www.example.com',
        localStorage: [{
          name: 'name2',
          value: 'value2'
        }]
      },
    ]
  });
  expect(context.pages()).toHaveLength(1);
  await page.goto('https://www.example.com');
  const localStorage2 = await page.evaluate('window.localStorage');
  expect(localStorage2).toEqual({ name2: 'value2' });

  await context.close();
});

it('should report good error if the url is not valid', async ({ contextFactory }) => {
  const error = await contextFactory({
    storageState: {
      cookies: [],
      origins: [
        {
          origin: 'foo',
          localStorage: [{
            name: 'name1',
            value: 'value1'
          }]
        },
      ]
    }
  }).catch(e => e);
  expect(error.message).toContain('browser.newContext: Error setting storage state:');
  expect(error.message).toContain('foo');
});

it('should round-trip through the file', async ({ contextFactory, channel }, testInfo) => {
  it.fixme(channel?.startsWith('msedge'), 'Network.clearBrowserCache sometimes stalls');

  const context = await contextFactory();
  const page1 = await context.newPage();
  await page1.route('**/*', route => {
    route.fulfill({ body: '<html></html>' }).catch(() => {});
  });
  await page1.goto('https://www.example.com');
  await page1.evaluate(async () => {
    localStorage['name1'] = 'value1';
    document.cookie = 'username=John Doe';

    await new Promise((resolve, reject) => {
      const openRequest = indexedDB.open('db', 42);
      openRequest.onupgradeneeded = () => {
        openRequest.result.createObjectStore('store', { keyPath: 'name' });
        openRequest.result.createObjectStore('store2');
      };
      openRequest.onsuccess = () => {
        const transaction = openRequest.result.transaction(['store', 'store2'], 'readwrite');
        transaction
            .objectStore('store')
            .put({ name: 'foo', date: new Date(0), null: null });
        transaction
            .objectStore('store2')
            .put(new TextEncoder().encode('bar'), 'foo');
        transaction.addEventListener('complete', resolve);
        transaction.addEventListener('error', reject);
      };
    });

    return document.cookie;
  });

  const path = testInfo.outputPath('storage-state.json');
  const state = await context.storageState({ path, indexedDB: true });
  const written = await fs.promises.readFile(path, 'utf8');
  expect(JSON.stringify(state, undefined, 2)).toBe(written);

  const checkContext = async (context: BrowserContext) => {
    const page = await context.newPage();
    await page.route('**/*', route => {
      route.fulfill({ body: '<html></html>' }).catch(() => {});
    });
    await page.goto('https://www.example.com');
    const localStorage = await page.evaluate('window.localStorage');
    expect(localStorage).toEqual({ name1: 'value1' });
    const cookie = await page.evaluate('document.cookie');
    expect(cookie).toEqual('username=John Doe');
    const idbValues = await page.evaluate(() => new Promise((resolve, reject) => {
      const openRequest = indexedDB.open('db', 42);
      openRequest.addEventListener('success', async () => {
        const db = openRequest.result;
        const transaction = db.transaction(['store', 'store2'], 'readonly');
        const request1 = transaction.objectStore('store').get('foo');
        const request2 = transaction.objectStore('store2').get('foo');

        const [result1, result2] = await Promise.all([request1, request2].map(request => new Promise((resolve, reject) => {
          request.addEventListener('success', () => resolve(request.result));
          request.addEventListener('error', () => reject(request.error));
        })));

        resolve([result1, new TextDecoder().decode(result2 as any)]);
      });
      openRequest.addEventListener('error', () => reject(openRequest.error));
    }));
    expect(idbValues).toEqual([
      { name: 'foo', date: new Date(0), null: null },
      'bar'
    ]);
  };

  const context2 = await contextFactory({ storageState: path });
  await checkContext(context2);
  await context2.close();

  const context3 = await contextFactory();
  await context3.setStorageState(path);
  expect(context3.pages()).toHaveLength(0);
  await checkContext(context3);
  await context3.close();
});

it('should round-trip OPFS', { annotation: { type: 'issue', description: 'https://github.com/microsoft/playwright/issues/41400' } }, async ({ browserName, contextFactory, page, server }, testInfo) => {
  it.skip(browserName === 'webkit', 'OPFS is unavailable in non-persistent WebKit contexts');

  await page.goto(server.EMPTY_PAGE);
  await page.evaluate(async () => {
    const root = await navigator.storage.getDirectory();
    const nested = await root.getDirectoryHandle('nested', { create: true });
    await nested.getDirectoryHandle('empty', { create: true });

    const binary = await nested.getFileHandle('data.bin', { create: true });
    const binaryWritable = await binary.createWritable();
    await binaryWritable.write(new Uint8Array([0, 1, 2, 255]));
    await binaryWritable.close();

    const text = await root.getFileHandle('hello.txt', { create: true });
    const textWritable = await text.createWritable();
    await textWritable.write('Hello, world!');
    await textWritable.close();
  });

  expect(await page.context().storageState()).toEqual({ cookies: [], origins: [] });

  const path = testInfo.outputPath('storage-state.json');
  const storageState = await page.context().storageState({ path, opfs: true });
  expect(storageState.origins).toEqual([{
    origin: server.PREFIX,
    localStorage: [],
    opfs: [
      { path: 'hello.txt', type: 'file', base64: 'SGVsbG8sIHdvcmxkIQ==' },
      { path: 'nested', type: 'directory' },
      { path: 'nested/data.bin', type: 'file', base64: 'AAEC/w==' },
      { path: 'nested/empty', type: 'directory' },
    ],
  }]);
  expect(JSON.parse(await fs.promises.readFile(path, 'utf8'))).toEqual(storageState);
  expect(await page.context().request.storageState({ opfs: true })).toEqual(storageState);

  const checkContext = async (context: BrowserContext) => {
    expect(await context.storageState({ opfs: true })).toEqual(storageState);
    const checkPage = await context.newPage();
    await checkPage.goto(server.EMPTY_PAGE);
    expect(await checkPage.evaluate(async () => {
      const root = await navigator.storage.getDirectory();
      const hello = await (await root.getFileHandle('hello.txt')).getFile();
      const nested = await root.getDirectoryHandle('nested');
      const data = await (await nested.getFileHandle('data.bin')).getFile();
      const empty = await nested.getDirectoryHandle('empty');
      const emptyEntries = [];
      for await (const name of empty.keys())
        emptyEntries.push(name);
      return {
        text: await hello.text(),
        bytes: [...new Uint8Array(await data.arrayBuffer())],
        empty: emptyEntries,
      };
    })).toEqual({
      text: 'Hello, world!',
      bytes: [0, 1, 2, 255],
      empty: [],
    });
  };

  const context2 = await contextFactory({ storageState: path });
  await checkContext(context2);
  await context2.close();

  const context3 = await contextFactory();
  const page3 = await context3.newPage();
  await page3.goto(server.EMPTY_PAGE);
  await page3.evaluate(async () => {
    const root = await navigator.storage.getDirectory();
    await root.getFileHandle('stale.txt', { create: true });
  });
  await context3.setStorageState(storageState);
  await checkContext(context3);
  await context3.close();
});

it('should capture cookies', async ({ server, context, page, contextFactory }) => {
  server.setRoute('/setcookie.html', (req, res) => {
    res.setHeader('Set-Cookie', ['a=b', 'empty=']);
    res.end();
  });

  await page.goto(server.PREFIX + '/setcookie.html');
  expect(await page.evaluate(() => {
    const cookies = document.cookie.split(';');
    return cookies.map(cookie => cookie.trim()).sort();
  })).toEqual([
    'a=b',
    'empty=',
  ]);

  const storageState = await context.storageState();
  expect(new Set(storageState.cookies)).toEqual(new Set([
    expect.objectContaining({
      name: 'a',
      value: 'b'
    }),
    expect.objectContaining({
      name: 'empty',
      value: ''
    })
  ]));
  const context2 = await contextFactory({ storageState });
  const page2 = await context2.newPage();
  await page2.goto(server.EMPTY_PAGE);
  expect(await page2.evaluate(() => {
    const cookies = document.cookie.split(';');
    return cookies.map(cookie => cookie.trim()).sort();
  })).toEqual([
    'a=b',
    'empty=',
  ]);
});

it('should not emit events about internal page', async ({ contextFactory }) => {
  const context = await contextFactory();
  const page = await context.newPage();
  await page.route('**/*', route => {
    void route.fulfill({ body: '<html></html>' });
  });
  await page.goto('https://www.example.com');
  await page.evaluate(() => localStorage['name1'] = 'value1');
  await page.goto('https://www.domain.com');
  await page.evaluate(() => localStorage['name2'] = 'value2');

  const events = [];
  context.on('page', e => events.push(e));
  context.on('request', e => events.push(e));
  context.on('requestfailed', e => events.push(e));
  context.on('requestfinished', e => events.push(e));
  context.on('response', e => events.push(e));
  await context.storageState();
  expect(events).toHaveLength(0);
});

it('should not restore localStorage twice', async ({ contextFactory }) => {
  const context = await contextFactory({
    storageState: {
      cookies: [],
      origins: [
        {
          origin: 'https://www.example.com',
          localStorage: [{
            name: 'name1',
            value: 'value1'
          }]
        },
      ]
    }
  });
  const page = await context.newPage();
  await page.route('**/*', route => {
    route.fulfill({ body: '<html></html>' }).catch(() => {});
  });
  await page.goto('https://www.example.com');
  const localStorage1 = await page.evaluate('window.localStorage');
  expect(localStorage1).toEqual({ name1: 'value1' });

  await page.evaluate(() => window.localStorage['name1'] = 'value2');

  await page.goto('https://www.example.com');
  const localStorage2 = await page.evaluate('window.localStorage');
  expect(localStorage2).toEqual({ name1: 'value2' });

  await context.close();
});

it('should handle missing file', async ({ contextFactory }, testInfo) => {
  const file = testInfo.outputPath('does-not-exist.json');
